{"supplier_name_rt":{"type":"keyword","script":{"source":"if (!doc.containsKey('supplier_id') || doc['supplier_id'].empty) {
  emit(null);
  return;
}

int sid = (int) doc['supplier_id'].value;

if (sid == 1) emit("Rodriguez PLC");
else if (sid == 2) emit("Griffin-Green");
else if (sid == 3) emit("Sutton, Owens and Griffin");
else if (sid == 4) emit("Davis Group");
else if (sid == 5) emit("Pollard Ltd");
else if (sid == 6) emit("Thomas, Daugherty and Walker");
else if (sid == 7) emit("Barrett-Taylor");
else if (sid == 8) emit("Graves-Carr");
else if (sid == 9) emit("Brooks-Guzman");
else if (sid == 10) emit("Richardson Ltd");
else emit("Supplier " + sid);
"}}}
